<?php $value=fn($key,$default='')=>is_post()?input($key,(string)$default):($entry[$key]??$default); ?>
<div class="page-heading"><div><a class="back-link" href="<?= e(url($type==='income'?'income':'expenses')) ?>"><?= icon('arrow-left') ?><?= $type==='income'?'Income':'Expenses' ?></a><h1><?= e($title) ?></h1><?php if($entry): ?><p><?= e($entry['description']) ?></p><?php endif ?></div><?php if($entry): ?><?= badge($entry['status']) ?><?php endif ?></div>
<?php if($error): ?><div class="notice error" role="alert"><?= e($error) ?></div><?php endif ?>
<div class="detail-layout"><section><form method="post" class="stack-form" action="<?= e(url('entry',$entry?['id'=>$entry['id']]:['type'=>$type])) ?>">
<?= csrf_field() ?><fieldset<?= !$editable?' disabled':'' ?>><legend>Entry details</legend><label>Description<input name="description" maxlength="190" value="<?= e($value('description')) ?>" required placeholder="e.g. Monthly software subscription"></label><div class="form-grid"><label>Total amount (<?= e(workspace()['currency']) ?>)<input type="number" name="amount" min="0.01" max="999999999.99" step="0.01" value="<?= e(is_post()?input('amount'):($entry?decimal((int)$entry['amount']):'')) ?>" required></label><label>Tax included<input type="number" name="tax_amount" min="0" step="0.01" value="<?= e(is_post()?input('tax_amount'):decimal((int)($entry['tax_amount']??0))) ?>" required></label><label>Entry date<input type="date" name="entry_date" value="<?= e($value('entry_date',date('Y-m-d'))) ?>" required></label><label>Reference<input name="reference" maxlength="100" value="<?= e($value('reference')) ?>" placeholder="Receipt or invoice number"></label><label>Category<select name="category_id"><option value="">Uncategorized</option><?php foreach($categories as $cat): ?><option value="<?= $cat['id'] ?>"<?= selected($value('category_id'),$cat['id']) ?>><?= e($cat['name']) ?></option><?php endforeach ?></select></label><label><?= $type==='income'?'Customer':'Supplier' ?><select name="contact_id"><option value="">No contact</option><?php foreach($contacts as $contact): ?><option value="<?= $contact['id'] ?>"<?= selected($value('contact_id'),$contact['id']) ?>><?= e($contact['name']) ?></option><?php endforeach ?></select></label><label>Status<select name="status" data-payment-status><?php $statuses=$editable?(can_manage()?($type==='income'?['draft','pending','paid']:['draft','pending','approved','paid']):['draft','pending']):[$entry['status']]; foreach($statuses as $s): ?><option value="<?= $s ?>"<?= selected($value('status','draft'),$s) ?>><?= ucfirst($s) ?></option><?php endforeach ?></select></label><label data-paid-date>Payment date<input type="date" name="paid_on" value="<?= e($value('paid_on',date('Y-m-d'))) ?>"></label></div><label>Notes<textarea name="notes" rows="4" maxlength="5000"><?= e($value('notes')) ?></textarea></label></fieldset>
<?php if($editable): ?><div class="form-actions"><button class="button primary" type="submit"><?= icon('check') ?>Save <?= e($type) ?></button><a class="button" href="<?= e(url($type==='income'?'income':'expenses')) ?>">Cancel</a></div><?php endif ?></form>
<?php if($entry&&$entry['review_note']): ?><div class="notice warning"><div><strong>Review note</strong><p><?= e($entry['review_note']) ?></p></div></div><?php endif ?>
<?php if($invoice): ?><p class="notice">Payment from <a class="text-link" href="<?= e(url('invoice',['id'=>$invoice['id']])) ?>"><?= e($invoice['number']) ?></a></p><?php endif ?>
<?php if($entry&&!$invoice): ?><section class="entry-actions"><h2>Actions</h2><form class="inline-form" method="post" action="<?= e(url('entry-action')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $entry['id'] ?>"><?php if(in_array($entry['status'],['draft','rejected'],true)): ?><button class="button primary" name="action" value="submit"><?= icon('upload') ?>Submit<?= $type==='expense'?' for approval':'' ?></button><button class="button danger" name="action" value="delete" data-confirm="Delete this draft entry? This cannot be undone.">Delete draft</button><?php endif ?><?php if(can_manage()&&$entry['status']==='pending'&&$type==='expense'): ?><button class="button primary" name="action" value="approve"><?= icon('check') ?>Approve</button><label class="review-reason"><span class="sr-only">Rejection reason</span><input name="review_note" maxlength="500" placeholder="Reason for rejection"></label><button class="button danger" name="action" value="reject"><?= icon('x') ?>Reject</button><?php endif ?><?php if(can_manage()&&(($entry['status']==='approved'&&$type==='expense')||($entry['status']==='pending'&&$type==='income'))): ?><label>Payment date<input type="date" name="paid_on" value="<?= date('Y-m-d') ?>" required></label><button class="button primary" name="action" value="paid"><?= icon('check-check') ?>Mark as paid</button><?php endif ?><?php if($entry['status']==='paid'): ?><p class="muted">Payment recorded on <?= short_date($entry['paid_on']) ?>. Finalized entries are locked.</p><?php endif ?></form></section><?php endif ?>
</section><aside class="detail-aside"><h2>Documents</h2><?php if(!$entry): ?><div class="empty-state compact"><?= icon('file-text') ?><p>Save this entry to attach documents.</p></div><?php else: ?><?php foreach($documents as $d): ?><a class="document-link" href="<?= e(url('document-download',['id'=>$d['id']])) ?>"><?= icon('file-text') ?><span><?= e($d['original_name']) ?><small><?= number_format($d['size']/1024,0) ?> KB</small></span><?= icon('download') ?></a><?php endforeach ?><?php if(!$documents): ?><p class="muted">No documents attached.</p><?php endif ?><form class="stack-form upload-form" method="post" enctype="multipart/form-data" action="<?= e(url('documents')) ?>"><?= csrf_field() ?><input type="hidden" name="entry_id" value="<?= $entry['id'] ?>"><label>Attach a document<input type="file" name="document" accept=".pdf,.png,.jpg,.jpeg,.webp" required><small>PDF, JPG, PNG or WebP &middot; Up to 10 MB</small></label><button class="button" type="submit"><?= icon('upload') ?>Upload document</button></form><?php endif ?></aside></div>
